  gs.info("[sn_wsd_indoor_map] : Started populated wsd_table and wsd_field in sn_wsd_indoor_map_place_properties_mapping table")
var propertiesMappingGr = new GlideRecord("sn_wsd_indoor_map_place_properties_mapping");
propertiesMappingGr.query();

while(propertiesMappingGr.next()) {
    propertiesMappingGr.setValue('wsd_table', "sn_wsd_core_room");
    propertiesMappingGr.setValue('wsd_field', propertiesMappingGr.getValue('wsd_space_column'));
    propertiesMappingGr.update();
}
gs.info("[sn_wsd_indoor_map] : Finished populated wsd_table and wsd_field in sn_wsd_indoor_map_place_properties_mapping table")
